/**
 * @name Path traversal via FileResponse
 * @description Untrusted input flowing to the FileResponse path argument can allow reading arbitrary files
 * @kind problem
 * @problem.severity error
 * @id py/aiohttp-fileresponse-path-traversal
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module FileResponsePathConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("aiohttp").getMember("web").getMember("FileResponse").getACall()
      and (sink = call.getArg(0) or sink = call.getArgByName("path"))
    )
  }
}

module FileResponsePathFlow = TaintTracking::Global<FileResponsePathConfig>;

from DataFlow::Node source, DataFlow::Node sink
where FileResponsePathFlow::flow(source, sink)
select sink, "Potential path traversal via FileResponse from $@.", source, "user input"

