/**
 * @name CookieJar.load pickle source check
 * @description Check what source data flows into pickle.load in CookieJar.load
 * @kind problem
 * @problem.severity warning
 * @id py/aiohttp-cookiejar-pickle-flow
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources

module CookieJarPickleConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(Call c |
      c.getFunc().(Attribute).getObject().(Name).getId() = "pickle" and
      c.getFunc().(Attribute).getAttr() = "load" and
      sink = DataFlow::exprNode(c.getArg(0))
    )
  }
}

module CookieJarPickleFlow = TaintTracking::Global<CookieJarPickleConfig>;

from DataFlow::Node source, DataFlow::Node sink
where CookieJarPickleFlow::flow(source, sink)
select sink, "Untrusted input reaches pickle.load from $@.", source, "user input"

